import{_ as e,o as n,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"传感器 (Sensors)","description":"","frontmatter":{},"headers":[],"relativePath":"sensors.md","filePath":"sensors.md","lastUpdated":1780850351000}'),p={name:"sensors.md"};function l(i,s,t,c,r,d){return n(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="传感器-sensors" tabindex="-1">传感器 (Sensors)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 22, 2022.</p><hr><p>sensors模块提供了获取手机上的传感器的信息的支持, 这些传感器包括距离传感器、光线光感器、重力传感器、方向传感器等. 需要指出的是, 脚本只能获取传感器的数据, <strong>不能模拟或伪造传感器的数据和事件</strong>, 因此诸如模拟摇一摇的功能是无法实现的.</p><p>要监听一个传感器时, 需要使用<code>sensors.register()</code>注册监听器, 之后才能开始监听；不需要监听时则调用<code>sensors.unregister()</code>注销监听器. 在脚本结束时会自动注销所有的监听器. 同时, 这种监听会使脚本保持运行状态, 如果不注销监听器, 脚本会一直保持运行状态.</p><p>例如, 监听光线传感器的代码为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//光线传感器监听</span></span>
<span class="line"><span>sensors.register(&quot;light&quot;).on(&quot;change&quot;, (event, light)=&gt;{</span></span>
<span class="line"><span>    log(&quot;当前光强度为&quot;, light);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>要注意的是, 每个传感器的数据并不相同, 所以对他们调用<code>on()</code>监听事件时的回调函数参数也不是相同, 例如光线传感器参数为<code>(event, light)</code>, 加速度传感器参数为<code>(event, ax, ay, az)</code>. 甚至在某些设备上的传感器参数有所增加, 例如华为手机的距离传感器为三个参数, 一般手机只有一个参数.</p><p>常用的传感器及其事件参数如下表：</p><ul><li><p><code>accelerometer</code> 加速度传感器, 参数<code>(event, ax, ay, az)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>ax</code> {number} x轴上的加速度, 单位m/s^2</li><li><code>ay</code> {number} y轴上的加速度, 单位m/s^2</li><li><code>az</code> {number} z轴上的加速度, 单位m/s^2 这里的x轴, y轴, z轴所属的坐标系统如下图(其中z轴垂直于设备屏幕表面):</li></ul><blockquote><p>坐标系统示意图待补充.</p></blockquote></li><li><p><code>orientation</code> 方向传感器, 参数<code>(event, azimuth, pitch, roll)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>azimuth</code> {number} 方位角, 从地磁指北方向线起, 依顺时针方向到y轴之间的水平夹角, 单位角度, 范围0~359</li><li><code>pitch</code> {number} 绕x轴旋转的角度, 当设备水平放置时该值为0, 当设备顶部翘起时该值为正数, 当设备尾部翘起时该值为负数, 单位角度, 范围-180~180</li><li><code>roll</code> {number} 绕y轴顺时针旋转的角度, 单位角度, 范围-90~90</li></ul></li><li><p><code>gyroscope</code> 陀螺仪传感器, 参数<code>(event, wx, wy, wz)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>wx</code> {number} 绕x轴的角速度, 单位弧度/s</li><li><code>wy</code> {number} 绕y轴的角速度, 单位弧度/s</li><li><code>wz</code> {number} 绕z轴的角速度, 单位弧度/s</li></ul></li><li><p><code>magnetic_field</code> 磁场传感器, 参数<code>(event, bx, by, bz)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>bx</code> {number} x轴上的磁场强度, 单位uT</li><li><code>by</code> {number} y轴上的磁场强度, 单位uT</li><li><code>bz</code> {number} z轴上的磁场强度, 单位uT</li></ul></li><li><p><code>gravity</code> 重力传感器, 参数<code>(event, gx, gy, gz)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>gx</code> {number} x轴上的重力加速度, 单位m/s^2</li><li><code>gy</code> {number} y轴上的重力加速度, 单位m/s^2</li><li><code>gz</code> {number} z轴上的重力加速度, 单位m/s^2</li></ul></li><li><p><code>linear_acceleration</code> 线性加速度传感器, 参数<code>(event, ax, ay, az)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>ax</code> {number} x轴上的线性加速度, 单位m/s^2</li><li><code>ay</code> {number} y轴上的线性加速度, 单位m/s^2</li><li><code>az</code> {number} z轴上的线性加速度, 单位m/s^2</li></ul></li><li><p><code>ambient_temperature</code> 环境温度传感器, 大部分设备并不支持, 参数<code>(event, t)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>t</code> {number} 环境温度, 单位摄氏度.</li></ul></li><li><p><code>light</code> 光线传感器, 参数<code>(event, light)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>light</code> {number} 环境光强度, 单位lux</li></ul></li><li><p><code>pressure</code> 压力传感器, 参数<code>(event, p)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>p</code> {number} 大气压, 单位hPa</li></ul></li><li><p><code>proximity</code> 距离传感器, 参数<code>(event, distance)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>distance</code> {number} 一般指设备前置摄像头旁边的距离传感器到前方障碍物的距离, 并且很多设备上这个值只有两种情况：当障碍物较近时该值为0, 当障碍物较远或在范围内没有障碍物时该值为5</li></ul></li><li><p><code>relative_humidity</code> 湿度传感器, 大部分设备并不支持, 参数<code>(event, rh)</code>:</p><ul><li><code>event</code> <a href="#sensors_sensorevent">SensorEvent</a> 传感器事件, 用于获取传感器数据变化时的所有信息</li><li><code>rh</code> {number} 相对湿度, 范围为0~100（百分比）</li></ul></li></ul><h2 id="sensors-register-sensorname-delay" tabindex="-1">sensors.register(sensorName[, delay])</h2><ul><li><code>sensorName</code> {string} 传感器名称, 常用的传感器名称如上面所述</li><li><code>delay</code> {number} 传感器数据更新频率, 可选, 默认为<code>sensors.delay.normal</code>. 可用的值如下： <ul><li><code>sensors.delay.normal</code> 正常频率</li><li><code>sensors.delay.ui</code> 适合于用户界面的更新频率</li><li><code>sensors.delay.game</code> 适合于游戏的更新频率</li><li><code>sensors.delay.fastest</code> 最快的更新频率】</li></ul></li><li>返回 <a href="#sensors_sensoreventemitter">SensorEventEmiiter</a></li></ul><p>注册一个传感器监听并返回<a href="#sensors_sensoreventemitter">SensorEventEmitter</a>.</p><p>例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>console.show();</span></span>
<span class="line"><span>//注册传感器监听</span></span>
<span class="line"><span>var sensor = sensors.register(&quot;gravity&quot;);</span></span>
<span class="line"><span>if(sensor == null){</span></span>
<span class="line"><span>    toast(&quot;不支持重力传感器&quot;);</span></span>
<span class="line"><span>    exit();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>//监听数据</span></span>
<span class="line"><span>sensor.on(&quot;change&quot;, (gx, gy, gz)=&gt;{</span></span>
<span class="line"><span>    log(&quot;重力加速度: %d, %d, %d&quot;, gx, gy, gz);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>可以通过delay参数来指定传感器数据的更新频率, 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var sensor = sensors.register(&quot;gravity&quot;, sensors.delay.game);</span></span></code></pre></div><p>另外, 如果不支持<code>sensorName</code>所指定的传感器, 那么该函数将返回<code>null</code>；但如果<code>sensors.ignoresUnsupportedSensor</code>的值被设置为<code>true</code>, 则该函数会返回一个不会分发任何传感器事件的<a href="#sensors_sensoreventemitter">SensorEventEmitter</a>.</p><p>例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sensors.ignoresUnsupportedSensor = true;</span></span>
<span class="line"><span>//无需null判断</span></span>
<span class="line"><span>sensors.register(&quot;gravity&quot;).on(&quot;change&quot;, (gx, gy, gz)=&gt;{</span></span>
<span class="line"><span>    log(&quot;重力加速度: %d, %d, %d&quot;, gx, gy, gz);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>更多信息, 参见<a href="#sensors_sensoreventemitter">SensorEventEmitter</a>和<a href="#sensors_sensors_ignoresUnsupportedSensor">sensors.ignoresUnsupportedSensor</a>.</p><h2 id="sensors-unregister-emitter" tabindex="-1">sensors.unregister(emitter)</h2><ul><li><code>emiiter</code> <a href="#sensors_sensoreventemitter">SensorEventEmitter</a></li></ul><p>注销该传感器监听器. 被注销的监听器将不再能监听传感器数据.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//注册一个传感器监听器</span></span>
<span class="line"><span>var sensor = sensors.register(&quot;gravity&quot;);</span></span>
<span class="line"><span>if(sensor == null){</span></span>
<span class="line"><span>    exit();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>//2秒后注销该监听器</span></span>
<span class="line"><span>setTimeout(()=&gt; {</span></span>
<span class="line"><span>    sensors.unregister(sensor);</span></span>
<span class="line"><span>}, 2000);</span></span></code></pre></div><h2 id="sensors-unregisterall" tabindex="-1">sensors.unregisterAll()</h2><p>注销所有传感器监听器.</p><h2 id="sensors-ignoresunsupportedsensor" tabindex="-1">sensors.ignoresUnsupportedSensor</h2><ul><li>{boolean}</li></ul><p>表示是否忽略不支持的传感器. 如果该值被设置为<code>true</code>, 则函数<code>sensors.register()</code>即使对不支持的传感器也会返回一个无任何数据的虚拟传感器监听, 也就是<code>sensors.register()</code>不会返回<code>null</code>从而避免非空判断, 并且此时会触发<code>sensors</code>的&quot;unsupported_sensor&quot;事件.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//忽略不支持的传感器</span></span>
<span class="line"><span>sensors.ignoresUnsupportedSensor = true;</span></span>
<span class="line"><span>//监听有不支持的传感器时的事件</span></span>
<span class="line"><span>sensors.on(&quot;unsupported_sensor&quot;, function(sensorName){</span></span>
<span class="line"><span>    toastLog(&quot;不支持的传感器: &quot; + sensorName);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>//随便注册一个不存在的传感器.</span></span>
<span class="line"><span>log(sensors.register(&quot;aaabbb&quot;));</span></span></code></pre></div><h2 id="事件-unsupported-sensor" tabindex="-1">事件: &#39;unsupported_sensor&#39;</h2><ul><li><code>sensorName</code> {string} 不支持的传感器名称</li></ul><p>当<code>sensors.ignoresUnsupportedSensor</code>被设置为<code>true</code>并且有不支持的传感器被注册时触发该事件. 事件参数的传感器名称.</p><h1 id="sensoreventemitter" tabindex="-1">SensorEventEmitter</h1><p>注册传感器返回的对象, 其本身是一个EventEmmiter, 用于监听传感器事件.</p><h2 id="事件-change" tabindex="-1">事件: &#39;change&#39;</h2><ul><li><code>..args</code> {Any} 传感器参数</li></ul><p>当传感器数据改变时触发该事件；该事件触发的最高频繁由<code>sensors.register()</code>指定的delay参数决定.</p><p>事件参数根据传感器类型不同而不同, 具体参见本章最前面的列表.</p><p>一个监听光线传感器和加速度传感器并且每0.5秒获取一个数据并最终写入一个csv表格文件的例子如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//csv文件路径</span></span>
<span class="line"><span>cosnt csvPath = &quot;/sdcard/sensors_data.csv&quot;;</span></span>
<span class="line"><span>//记录光线传感器的数据</span></span>
<span class="line"><span>var light = 0;</span></span>
<span class="line"><span>//记录加速度传感器的数据</span></span>
<span class="line"><span>var ax = 0;</span></span>
<span class="line"><span>var ay = 0;</span></span>
<span class="line"><span>var az = 0;</span></span>
<span class="line"><span>//监听光线传感器</span></span>
<span class="line"><span>sensors.register(&quot;light&quot;, sensors.delay.fastest)</span></span>
<span class="line"><span>    .on(&quot;change&quot;, l =&gt; {</span></span>
<span class="line"><span>        light = l;</span></span>
<span class="line"><span>    });</span></span>
<span class="line"><span>//监听加速度传感器</span></span>
<span class="line"><span>sensors.register(&quot;accelerometer&quot;, sensors.delay.fastest)</span></span>
<span class="line"><span>    .on(&quot;change&quot;, (ax0, ay0, az0) =&gt; {</span></span>
<span class="line"><span>        ax = ax0;</span></span>
<span class="line"><span>        ay = ay0;</span></span>
<span class="line"><span>        az = az0;</span></span>
<span class="line"><span>    });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>var file = open(csvPath, &quot;w&quot;);</span></span>
<span class="line"><span>//写csv表格头</span></span>
<span class="line"><span>file.writeline(&quot;light,ax,ay,az&quot;)</span></span>
<span class="line"><span>//每0.5秒获取一次数据并写入文件</span></span>
<span class="line"><span>setInterval(()=&gt;{</span></span>
<span class="line"><span>    file.writeline(util.format(&quot;%d,%d,%d,%d&quot;, light, ax, ay, az));</span></span>
<span class="line"><span>}, 500);</span></span>
<span class="line"><span>//10秒后退出并打开文件</span></span>
<span class="line"><span>setTimeout(()=&gt;{</span></span>
<span class="line"><span>    file.close();</span></span>
<span class="line"><span>    sensors.unregsiterAll();</span></span>
<span class="line"><span>    app.viewFile(csvPath);</span></span>
<span class="line"><span>}, 10 * 1000);</span></span></code></pre></div><h2 id="事件-accuracy-change" tabindex="-1">事件: &#39;accuracy_change&#39;</h2><ul><li><code>accuracy</code> {number} 表示传感器精度. 为以下值之一: <ul><li>-1 传感器未连接</li><li>0 传感器不可读</li><li>1 低精度</li><li>2 中精度</li><li>3 高精度</li></ul></li></ul><p>当传感器精度改变时会触发的事件. 比较少用.</p>`,47)])])}const h=e(p,[["render",l]]);export{g as __pageData,h as default};
